const axios = require('axios');
const authService = require('./auth');
const MOSIPDecryptor = require('../utils/decryptor');
const fs = require('fs');
const path = require('path');
const { URL } = require('url');
const EventEmitter = require('events');
const Decryptor = require('../utils/decryptor');
const logger = require('./logger');

class DataShareService extends EventEmitter {
  constructor() {
    super();
    this.config = {
      mode: process.env.DATA_SOURCE_MODE || 'datashare', // 'direct' or 'datashare'
      directMessagePath: process.env.DIRECT_MESSAGE_PATH || 'event.data.credential',
      dataShareBaseUrl: process.env.DATASHARE_BASE_URL || '',
      registrationIdField: process.env.REGISTRATION_ID_FIELD || 'event.data.registrationId',
      decryption: {
        p12Path: process.env.P12_PATH || '',
        p12Password: process.env.P12_PASSWORD || '',
        tempEncryptedFile: process.env.TEMP_ENCRYPTED_FILE || path.join(process.cwd(), 'temp', 'encrypted.txt'),
        tempDecryptedFile: process.env.TEMP_DECRYPTED_FILE || path.join(process.cwd(), 'temp', 'decrypted.txt')
      }
    };
    
    // Create temp directory if it doesn't exist
    const tempDir = path.dirname(this.config.decryption.tempEncryptedFile);
    if (!fs.existsSync(tempDir)) {
      fs.mkdirSync(tempDir, { recursive: true });
    }
    
    // Cached decryptor instance for reuse
    this.decryptor = null;
  }

  updateConfig(config) {
    if (config) {
      // Handle nested structure
      if (config.decryption) {
        this.config.decryption = {
          ...this.config.decryption,
          ...config.decryption
        };
        
        // Reset decryptor cache if p12 configuration changes
        if (config.decryption.p12Path || config.decryption.p12Password) {
          this.decryptor = null;
        }
        
        delete config.decryption;
      }
      
      // Update top level properties
      Object.assign(this.config, config);
      
      logger.debug('DataShare service configuration updated', {
        mode: this.config.mode,
        directMessagePath: this.config.directMessagePath,
        registrationIdField: this.config.registrationIdField
      });
    }
    return this;
  }

  /**
   * Get or create decryptor instance
   * @private
   */
  _getDecryptor() {
    // Create decryptor if it doesn't exist or if configuration has changed
    if (!this.decryptor) {
      logger.debug('Creating new decryptor instance');
      this.decryptor = new MOSIPDecryptor({
        p12Path: this.config.decryption.p12Path,
        p12Password: this.config.decryption.p12Password,
        inputFilePath: this.config.decryption.tempEncryptedFile,
        outputFilePath: this.config.decryption.tempDecryptedFile
      });
    }
    return this.decryptor;
  }

  /**
   * Retrieve data from the DataShare URI
   */
  async retrieveData(dataShareUri) {
    try {
      if (!dataShareUri) {
        throw new Error('DataShare URI is required');
      }
      
      this.emit('status', 'retrieving_data');
      
      // Determine the full URI to use (handle prefix replacement)
      let fullUri = dataShareUri;
      
      try {
        // Check if we need to replace the domain with our configured baseUrl
        if (this.config.dataShareBaseUrl) {
          logger.info(`DataShare base URL configured: ${this.config.dataShareBaseUrl}`);
          
          // If it's a relative path, simply append to base URL
          if (!dataShareUri.startsWith('http')) {
            fullUri = `${this.config.dataShareBaseUrl}${dataShareUri.startsWith('/') ? '' : '/'}${dataShareUri}`;
            logger.info(`Using relative path with base URL: ${fullUri}`);
          } else {
            // If it's an absolute URL, we might need to replace the domain
            const originalUrl = new URL(dataShareUri);
            const baseUrl = new URL(this.config.dataShareBaseUrl);
            
            // Create a new URL with the baseUrl's origin but keep the original path and query
            fullUri = `${baseUrl.origin}${originalUrl.pathname}${originalUrl.search}`;
            logger.info(`Replaced domain in DataShare URI: ${fullUri}`);
          }
        }
      } catch (urlError) {
        logger.error('Error processing URL:', urlError.message);
        // Fall back to the original URI if URL processing fails
        fullUri = dataShareUri;
      }
      
      logger.info(`Retrieving data from DataShare URI: ${fullUri}`);
      
      // Get authentication token
      const token = await authService.authenticate();
      
      // Make API request to get encrypted data
      let response;
      try {
        response = await axios.get(fullUri, {
          headers: {
            'Authorization': token,
            'Cookie': `Authorization=${token}`
          }
        });
      } catch (fetchError) {
        // If hostname not found (ENOTFOUND) and we haven't tried with our base URL yet
        // or if the current URL doesn't start with our base URL
        if (fetchError.code === 'ENOTFOUND' && this.config.dataShareBaseUrl) {
          logger.warn('Cannot resolve hostname, trying alternative URL construction...');
          
          try {
            // Extract the path from the original URI if it's a full URL
            let path;
            if (dataShareUri.startsWith('http')) {
              const url = new URL(dataShareUri);
              path = url.pathname + url.search;
            } else {
              path = dataShareUri.startsWith('/') ? dataShareUri : `/${dataShareUri}`;
            }
            
            // Construct a new URI with the configured base URL
            const fallbackUri = `${this.config.dataShareBaseUrl}${path}`;
            logger.info('Trying fallback URI:', fallbackUri);
            
            // Try the request with the fallback URI
            response = await axios.get(fallbackUri, {
              headers: {
                'Authorization': token,
                'Cookie': `Authorization=${token}`
              }
            });
          } catch (fallbackError) {
            logger.error('Failed with fallback URI as well:', fallbackError.message);
            throw fallbackError;
          }
        } else {
          throw fetchError;
        }
      }
      
      if (response.status !== 200) {
        throw new Error(`Failed to retrieve data: ${response.status} ${response.statusText}`);
      }
      
      const encryptedData = response.data;
      
      // Check if the response is a string (encrypted data) or an object
      if (typeof encryptedData !== 'string') {
        logger.warn('Retrieved data is not encrypted or in unexpected format');
        return encryptedData;
      }
      
      // Save encrypted data to temporary file if configured
      if (this.config.decryption.tempEncryptedFile) {
        const tempDir = path.dirname(this.config.decryption.tempEncryptedFile);
        if (!fs.existsSync(tempDir)) {
          fs.mkdirSync(tempDir, { recursive: true });
        }
        
        fs.writeFileSync(this.config.decryption.tempEncryptedFile, encryptedData);
      }
      
      // Return the encrypted data
      return encryptedData;
    } catch (error) {
      logger.error('Error retrieving data from DataShare:', error.message);
      if (error.response) {
        logger.error('Response status:', error.response.status);
        logger.error('Response data:', error.response.data);
      }
      throw error;
    }
  }

  /**
   * Decrypt data using MOSIP decryptor
   */
  decryptData(encryptedData) {
    try {
      if (!encryptedData) {
        throw new Error('No encrypted data provided');
      }
      
      this.emit('status', 'decrypting_data');
      
      // Validate decryption configuration
      if (!this.config.decryption.p12Path) {
        throw new Error('P12 path not configured');
      }
      
      // Get cached or create new decryptor instance
      const decryptor = this._getDecryptor();
      
      // Decrypt data
      let decryptedData;
      
      if (this.config.decryption.tempEncryptedFile && 
          fs.existsSync(this.config.decryption.tempEncryptedFile) && 
          typeof encryptedData !== 'string') {
        // If tempEncryptedFile exists and encryptedData is not a string, decrypt from file
        decryptedData = decryptor.decrypt();
      } else {
        // Decrypt directly from string
        decryptedData = decryptor.decryptData(encryptedData);
      }
      
      // Parse decrypted data as JSON if possible
      try {
        return JSON.parse(decryptedData);
      } catch (e) {
        // Return as string if not valid JSON
        return decryptedData.toString();
      }
    } catch (error) {
      logger.error('Decryption failed:', error.message);
      return { error: error.message };
    }
  }

  /**
   * Extract value from object using dot notation
   */
  extractValueByPath(obj, path) {
    if (!path) return obj;
    
    const keys = path.split('.');
    let result = obj;
    
    for (const key of keys) {
      if (result && typeof result === 'object' && key in result) {
        result = result[key];
      } else {
        return undefined;
      }
    }
    
    return result;
  }

  /**
   * Process notification data based on data source mode
   */
  async processNotification(notification) {
    try {
      if (!notification) {
        throw new Error('No notification data provided');
      }
      
      this.emit('status', 'processing_notification');
      logger.info('Processing notification in mode:', this.config.mode);
      
      // Extract registration ID from notification
      const registrationId = this.extractValueByPath(notification, this.config.registrationIdField);
      logger.info('Extracted registration ID:', registrationId);
      
      let encryptedData;
      
      if (this.config.mode === 'datashare') {
        // DataShare mode - extract URI and retrieve data
        const dataShareUri = this.extractValueByPath(notification, 'event.dataShareUri');
        
        if (!dataShareUri) {
          throw new Error('DataShare URI not found in notification');
        }
        
        encryptedData = await this.retrieveData(dataShareUri);
      } else if (this.config.mode === 'direct') {
        // Direct mode - extract encrypted data directly from notification
        encryptedData = this.extractValueByPath(notification, this.config.directMessagePath);
        
        if (!encryptedData) {
          throw new Error(`Encrypted data not found at path: ${this.config.directMessagePath}`);
        }
      } else {
        throw new Error(`Unsupported data source mode: ${this.config.mode}`);
      }
      
      // Decrypt the data
      const decryptedData = this.decryptData(encryptedData);
      
      // Add registration ID to the result
      if (registrationId) {
        if (typeof decryptedData === 'object' && decryptedData !== null) {
          decryptedData.registrationId = registrationId;
        } else {
          return {
            data: decryptedData,
            registrationId: registrationId
          };
        }
      }
      
      return decryptedData;
    } catch (error) {
      logger.error('Error processing notification:', error.message);
      return { error: error.message, mode: this.config.mode };
    }
  }
}

module.exports = new DataShareService(); 